package com.pratik.imagetap;
import android.content.Context;import android.view.*;import android.widget.*;import android.util.TypedValue;
/** Sizes real window bounds and children together, preserving hit-test geometry. */
final class PopupSize {
 static float scale(Context c,String key,float widthDp,float heightDp){float requested=Math.max(75,Math.min(150,c.getSharedPreferences("config",0).getInt(key,100)))/100f;android.util.DisplayMetrics m=c.getResources().getDisplayMetrics();return Math.min(requested,Math.min((float)m.widthPixels/Ui.dp(c,widthDp),(float)m.heightPixels/Ui.dp(c,heightDp)));}
 static void tree(View v,float s){v.setPadding(Math.round(v.getPaddingLeft()*s),Math.round(v.getPaddingTop()*s),Math.round(v.getPaddingRight()*s),Math.round(v.getPaddingBottom()*s));ViewGroup.LayoutParams p=v.getLayoutParams();if(p!=null){if(p.width>0)p.width=Math.round(p.width*s);if(p.height>0)p.height=Math.round(p.height*s);if(p instanceof ViewGroup.MarginLayoutParams){ViewGroup.MarginLayoutParams q=(ViewGroup.MarginLayoutParams)p;q.leftMargin=Math.round(q.leftMargin*s);q.rightMargin=Math.round(q.rightMargin*s);q.topMargin=Math.round(q.topMargin*s);q.bottomMargin=Math.round(q.bottomMargin*s);}}v.setMinimumWidth(Math.round(v.getMinimumWidth()*s));v.setMinimumHeight(Math.round(v.getMinimumHeight()*s));if(v instanceof TextView)((TextView)v).setTextSize(TypedValue.COMPLEX_UNIT_PX,((TextView)v).getTextSize()*s);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)tree(((ViewGroup)v).getChildAt(i),s);}
 static void fit(View view,WindowManager.LayoutParams p,Context c){android.util.DisplayMetrics m=c.getResources().getDisplayMetrics();p.width=Math.min(p.width,m.widthPixels);view.measure(View.MeasureSpec.makeMeasureSpec(p.width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(m.heightPixels,View.MeasureSpec.AT_MOST));p.x=Math.max(0,Math.min(p.x,m.widthPixels-p.width));p.y=Math.max(0,Math.min(p.y,m.heightPixels-view.getMeasuredHeight()));}
}
